class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            pre = [0] * (nums[i - 1] + 2)
            for v in range(nums[i - 1] + 1):
                pre[v + 1] = (pre[v] + dp[v]) % MOD
            ndp = [0] * (nums[i] + 1)
            for v in range(nums[i] + 1):
                hi = v + nums[i - 1] - nums[i]
                if hi >= 0:
                    ndp[v] = pre[min(hi, nums[i - 1]) + 1]
            dp = ndp
        return sum(dp) % MOD

