class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<long long> dp(nums[0] + 1, 1);
        for (int i = 1; i < n; i++) {
            vector<long long> pre(nums[i - 1] + 2, 0);
            for (int v = 0; v <= nums[i - 1]; v++)
                pre[v + 1] = (pre[v] + dp[v]) % MOD;
            vector<long long> ndp(nums[i] + 1, 0);
            for (int v = 0; v <= nums[i]; v++) {
                int hi = v + nums[i - 1] - nums[i];
                if (hi >= 0) ndp[v] = pre[min(hi, nums[i - 1]) + 1];
            }
            dp = ndp;
        }
        long long ans = 0;
        for (long long v : dp) ans = (ans + v) % MOD;
        return ans;
    }
};

