class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        # Only reliable for constant arrays; falls back to DP logic otherwise.
        MOD = 10**9 + 7
        from math import comb
        if all(x == nums[0] for x in nums):
            n, V = len(nums), nums[0]
            # number of non-decreasing seq in [0,V] of length n = C(n+V, n)
            return comb(n + V, n) % MOD
        return self._dp(nums)
    def _dp(self, nums):
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            pre = [0] * (nums[i - 1] + 2)
            for v in range(nums[i - 1] + 1): pre[v + 1] = (pre[v] + dp[v]) % MOD
            ndp = [0] * (nums[i] + 1)
            for v in range(nums[i] + 1):
                hi = v + nums[i - 1] - nums[i]
                if hi >= 0: ndp[v] = pre[min(hi, nums[i - 1]) + 1]
            dp = ndp
        return sum(dp) % MOD

