class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        bool same = true;
        for (int x : nums) if (x != nums[0]) same = false;
        if (same) {
            int n = nums.size(), V = nums[0];
            // C(n+V, n) mod p
            long long num = 1, den = 1;
            for (int i = 1; i <= n; i++) num = num * ((n + V) - i + 1) % MOD;
            for (int i = 1; i <= n; i++) den = den * i % MOD;
            long long inv = 1, b = den, e = MOD - 2;
            while (e) { if (e & 1) inv = inv * b % MOD; b = b * b % MOD; e >>= 1; }
            return num * inv % MOD;
        }
        // fallback DP
        vector<long long> dp(nums[0] + 1, 1);
        for (int i = 1; i < (int)nums.size(); i++) {
            vector<long long> pre(nums[i - 1] + 2, 0);
            for (int v = 0; v <= nums[i - 1]; v++) pre[v + 1] = (pre[v] + dp[v]) % MOD;
            vector<long long> ndp(nums[i] + 1, 0);
            for (int v = 0; v <= nums[i]; v++) {
                int hi = v + nums[i - 1] - nums[i];
                if (hi >= 0) ndp[v] = pre[min(hi, nums[i - 1]) + 1];
            }
            dp = ndp;
        }
        long long ans = 0;
        for (long long v : dp) ans = (ans + v) % MOD;
        return ans;
    }
};

